import gmpy2
import requests

# Provided RSA modulus (N)
N = 

# URL to download a list of known RSA moduli
MODULI_URL = "https://factordb.com/download_moduli.txt"

def fetch_known_moduli():
    response = requests.get(MODULI_URL)
    if response.status_code == 200:
        return response.text.splitlines()
    else:
        print("Failed to fetch moduli list.")
        return []

def find_shared_factors(N, known_moduli):
    for mod in known_moduli:
        try:
            mod_int = int(mod)
            gcd = gmpy2.gcd(N, mod_int)
            if gcd > 1:
                print(f"Shared factor found: gcd({N}, {mod}) = {gcd}")
                return gcd
        except ValueError:
            continue
    return None

def main():
    print("Fetching known RSA moduli...")
    known_moduli = fetch_known_moduli()

    print(f"Number of known moduli fetched: {len(known_moduli)}")
    print("Finding shared factors...")
    shared_factor = find_shared_factors(N, known_moduli)

    if shared_factor:
        print(f"Shared factor detected: {shared_factor}")
    else:
        print("No shared factors detected!")

if __name__ == "__main__":
    main()
